export const fetchMessages = createAsyncThunk('messages/fetch', getMessages);

// extraReducers
builder
  .addCase(fetchMessages.pending, (state) => { state.status = 'loading'; })
  .addCase(fetchMessages.fulfilled, (state, action) => {
    state.status = 'succeeded';
    state.list = action.payload;
  })
  .addCase(fetchMessages.rejected, (state) => { state.status = 'failed'; });

function UserBadge() {
  const state = useSelector((state) => state);
  return <span>{state.user.name}</span>;
}

const selectPrioritaires = createSelector(
